"""Generate out/brief-a.workflow.json for Brief A (Freya Bank, early-stage collections)."""
import json, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1/"

# ---------------------------------------------------------------- code snippets (no double braces allowed)
FACTS_CODE = r'''
import datetime, json, re
HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
DN = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def say(d):
    return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year) + ' (' + d.isoformat() + ')'
def nth_bd(start, n):
    d = start
    c = 0
    while c < n:
        d = d + ONE
        if isbd(d):
            c += 1
    return d
def next_bd(d):
    d = d + ONE
    while not isbd(d):
        d = d + ONE
    return d
def money(x):
    try:
        return '{:,.2f}'.format(float(x))
    except Exception:
        return str(x)
try:
    s = str(vars.get('now') or '').strip()
    dt = datetime.datetime.fromisoformat(s[:16])
except Exception:
    dt = datetime.datetime(2026, 10, 14, 11, 0)
today = dt.date()
hhmm = '%02d:%02d' % (dt.hour, dt.minute)
monday = today - datetime.timedelta(days=today.weekday())
dl = {'early': nth_bd(today, 12), 'late': nth_bd(today, 7)}
# attempt 1 date: last business day of this week, or of next week if today is that day or later
def last_bd_of_week(mon):
    d = mon + datetime.timedelta(days=6)
    while not isbd(d):
        d = d - ONE
    return d
a1 = last_bd_of_week(monday)
if a1 <= today:
    a1 = last_bd_of_week(monday + datetime.timedelta(days=7))
nbd = next_bd(today)
# calendar text
lines = []
end = dl['early'] + datetime.timedelta(days=10)
d = today - datetime.timedelta(days=today.weekday())
while d <= end:
    tag = []
    if d == today:
        tag.append('TODAY')
    if d < today:
        tag.append('past')
    if d.weekday() >= 5:
        tag.append('weekend, not a business day')
    elif d.isoformat() in HOL:
        tag.append('bank holiday, not a business day')
    else:
        tag.append('business day')
    if d >= monday and d < monday + datetime.timedelta(days=7):
        tag.append('this ' + DN[d.weekday()])
    elif d >= monday + datetime.timedelta(days=7) and d < monday + datetime.timedelta(days=14):
        tag.append('next ' + DN[d.weekday()])
    lines.append('- ' + say(d) + ': ' + ', '.join(tag))
    d = d + ONE
vars['today_text'] = say(today)
vars['today_iso'] = today.isoformat()
vars['now_time'] = hhmm
vars['calendar_text'] = '\n'.join(lines)
today_cb = 'later than ' + hhmm + ' and no later than 19:00' if hhmm < '19:00' else 'not possible any more'
if hhmm < '10:00':
    today_cb = 'from 10:00 to 19:00'
vars['callback_facts'] = ('Allowed callback slots: today ' + say(today) + ' ' + today_cb + '; or the next business day ' + say(nbd) +
    ' from 10:00 to 19:00 (both included). Nothing else is allowed: no other day, nothing before 10:00, nothing after 19:00.')
# ---------------- account part (only when the account was fetched)
prods = vars.get('products')
if isinstance(prods, str):
    t = prods.strip()
    try:
        prods = json.loads(t)
    except Exception:
        try:
            prods = json.loads(t.replace("'", '"').replace('True', 'true').replace('False', 'false').replace('None', 'null'))
        except Exception:
            prods = None
if isinstance(prods, dict):
    prods = [prods]
if not isinstance(prods, list) or not prods:
    p = {}
    for k in list(vars.keys()):
        m = re.match(r'^get_account_response\.data\.products\.0\.(\w+)$', str(k))
        if m:
            p[m.group(1)] = vars.get(k)
    prods = [p] if p else []
p = prods[0] if prods and isinstance(prods[0], dict) else {}
if p.get('product_id') and p.get('past_due') is not None:
    typ = str(p.get('type') or '')
    if typ == 'credit_card':
        phrase = 'credit card ending ' + str(p.get('card_last4') or '')
        floor = p.get('minimum_payment')
        floor_name = 'minimum payment'
    elif typ == 'car_loan':
        phrase = 'car loan'
        floor = p.get('instalment_amount')
        floor_name = 'instalment amount'
    else:
        phrase = 'personal loan'
        floor = p.get('instalment_amount')
        floor_name = 'instalment amount'
    try:
        days = int(float(p.get('days_late') or 0))
    except Exception:
        days = 0
    band = 'early' if days <= 7 else 'late'
    dline = dl[band]
    attempts = 1 if band == 'early' else 2
    valid = []
    d = today
    while d <= dline:
        if isbd(d):
            valid.append(say(d))
        d = d + ONE
    full = money(p.get('past_due'))
    fl = money(floor)
    vars['product_id'] = str(p.get('product_id'))
    vars['product_phrase'] = phrase
    vars['past_due_text'] = full
    vars['days_late_text'] = str(days)
    vars['account_state'] = 'ok'
    f = []
    f.append('Today: ' + say(today) + ', time ' + hhmm + '.')
    f.append('Product: ' + phrase + ' (product_id ' + str(p.get('product_id')) + ').')
    f.append('FULL past-due amount: ' + full + '. Days late: ' + str(days) + ' (' + band + ' band).')
    f.append('FLOOR (' + floor_name + '): ' + fl + '. No amount below ' + fl + ' can be recorded. No amount above ' + full + ' can be recorded.')
    f.append('DEADLINE (latest promise date): ' + say(dline) + '.')
    f.append('VALID PROMISE DATES (the only dates you may record): ' + '; '.join(valid) + '.')
    f.append('Persuasion attempts allowed in this call: ' + str(attempts) + '.')
    f.append('ATTEMPT 1 offer: the full amount ' + full + ' (or the floor ' + fl + ' if the customer already said the full amount is too much) on ' + say(a1) + '.')
    if attempts == 2:
        f.append('ATTEMPT 2 offer: the floor ' + fl + ' on the deadline ' + say(dline) + '.')
    else:
        f.append('There is NO attempt 2 in this call (early band). After attempt 1 is refused, close as refused.')
    vars['account_facts'] = '\n'.join(f)
else:
    vars['account_state'] = 'error' if vars.get('get_account_success_count') or vars.get('get_account_failure_count') or vars.get('get_account_response.status') else 'none'
    for k in ['product_id', 'product_phrase', 'past_due_text', 'days_late_text', 'account_facts']:
        if vars.get(k) is None:
            vars[k] = ''
'''

# ---------------------------------------------------------------- post hooks
def hook(body):
    return "try:\n    if isinstance(result, dict):\n        result.pop('header', None)\n        d = result.get('data')\n        if not isinstance(d, dict):\n            d = dict()\n            result['data'] = d\n" + "".join("        " + l + "\n" for l in body.strip("\n").split("\n")) + "except Exception:\n    pass\n"

VERIFY_POST = hook(r'''
if d.get('hint') == 'day_month_swapped':
    d['what_to_do_next'] = 'Not accepted yet, and this does NOT count as a wrong answer. Ask the customer to say their date of birth again with the month as a word, for example 14 March 1988.'
elif d.get('ok') is False and 'verified' not in d:
    d['what_to_do_next'] = 'The answer could not be checked (unreadable or a technical problem). This is not a wrong answer. Tell the customer briefly and ask for the same answer again.'
elif d.get('all_verified') is True:
    d['what_to_do_next'] = 'Both security answers are correct. Say thank you.'
elif d.get('verified') is True:
    d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'
elif d.get('wrong_answers_left') == 0:
    d['what_to_do_next'] = 'Third wrong answer: the check has ended. Do not ask again and do not mention any account details.'
else:
    d['what_to_do_next'] = 'The answer does not match our records. Tell the customer it does not match and ask the SAME question once more. Do not reveal the right answer.'
if result.get('status') not in (None, 'success') and 'verified' not in d:
    d['what_to_do_next'] = 'The check failed because of a technical problem. Tell the customer, then ask for the same answer again.'
''')

PROMISE_POST = hook(r'''
if d.get('ok') is True:
    d['what_to_do_next'] = 'The promise is recorded.'
else:
    d['ok'] = False
    d['what_to_do_next'] = 'FAILED: the promise was NOT recorded. Never say it is recorded. If this is the first failed create_promise in this call: tell the customer there was a technical problem and you will try again, and call create_promise again right now with exactly the same amount and date. If create_promise already failed once before in this call: tell the customer you could not record the promise, thank them, say goodbye and call close_call with outcome no_promise and reason service_error.'
''')

CALLBACK_POST = hook(r'''
if d.get('ok') is True:
    d['what_to_do_next'] = 'The callback is booked. Thank the person, say goodbye, and call close_call with outcome not_reached and reason callback.'
else:
    d['ok'] = False
    d['what_to_do_next'] = 'FAILED: the callback was NOT booked. Do not say it is booked. Try schedule_callback once more with the same date and time. If it fails again, tell the person you could not book it, say goodbye and call close_call with outcome not_reached and reason no_callback.'
''')

TRANSFER_POST = hook(r'''
if d.get('ok') is True:
    d['what_to_do_next'] = 'The transfer is arranged. Tell the customer a colleague will take over now, thank them, say goodbye, and call close_call with outcome transferred and the reason that matches the queue (restructuring -> restructuring, support -> support, general -> human).'
else:
    d['ok'] = False
    d['what_to_do_next'] = 'FAILED: the transfer did NOT work. Tell the customer you could not connect them. Try transfer_to_agent once more with the same queue.'
''')

CLOSE_PRE = "try:\n    b = config.get('body')\n    if isinstance(b, dict) and b.get('outcome') in ('promise', 'paid'):\n        b.pop('reason', None)\nexcept Exception:\n    pass\n"
PROMISE_PRE = ("try:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = b.get('amount')\n        if isinstance(a, str):\n            b['amount'] = float(a.replace(',', '').strip())\n"
               "        dt = b.get('date')\n        if isinstance(dt, str):\n            b['date'] = dt.strip()[:10]\nexcept Exception:\n    pass\n")


def api_tool(name, body_props, required, description, post="", pre="", retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": description,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": BASE + name},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if post:
        t["post_process_code"] = post
    if pre:
        t["pre_process_code"] = pre
    return t


def close_tool(allowed):
    """allowed: list of (outcome, reason-or-None) pairs this node may use."""
    outs = sorted({o for o, _ in allowed})
    reasons = sorted({r for _, r in allowed if r})
    combos = "; ".join(o + (" / " + r if r else " (no reason)") for o, r in allowed)
    props = {
        "outcome": {"type": "string", "enum": outs, "default": "{{close_outcome}}", "description": "Outcome of the call. Allowed combinations here: " + combos},
    }
    if reasons:
        props["reason"] = {"type": "string", "enum": reasons, "default": "{{close_reason}}", "description": "Reason that goes with the outcome. Allowed combinations: " + combos + ". Leave empty for promise or paid."}
    return api_tool("close_call", props, ["outcome"],
                    "Ends the call record. CALL it exactly once, as the very last action, in the same message in which you thank the customer and say goodbye. Allowed outcome / reason combinations: " + combos + ".",
                    pre=CLOSE_PRE, retries=1)


def verify_tool(field, desc):
    return api_tool("verify_identity", {
        "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "default": field},
        "answer": {"type": "string", "default": "{{security_answer}}", "description": desc},
    }, ["answer"], "Checks one security answer. CALL it every time the customer gives an answer to the security question, before you say anything about whether it is right.",
        post=VERIFY_POST, retries=1)


def transfer_tool(queue=None):
    if queue:
        q = {"type": "string", "enum": ["restructuring", "general", "support"], "default": queue}
        d = "Hands the call to a human colleague (queue " + queue + "). CALL it only when the customer insists on speaking to a human after you asked once whether you can help."
    else:
        q = {"type": "string", "enum": ["restructuring", "general", "support"], "default": "{{transfer_queue}}",
             "description": "restructuring: customer asks for a new payment plan or lower instalments. support: customer in hardship (illness, death in family, job loss) accepted the offer of the support team. general: customer insists on a human."}
        d = "Hands the call to a human team. CALL it for: a request for a new payment plan or lower instalments (queue restructuring), a hardship customer who accepted the support team (queue support), a customer who insists on a human after you asked once whether you can help (queue general)."
    return api_tool("transfer_to_agent", {"queue": q}, ["queue"], d, post=TRANSFER_POST, retries=0)


def callback_tool():
    return api_tool("schedule_callback", {
        "date": {"type": "string", "default": "{{callback_date}}", "description": "Callback date, YYYY-MM-DD. Must be one of the allowed callback days."},
        "time": {"type": "string", "default": "{{callback_time}}", "description": "Callback time, HH:MM 24-hour, from 10:00 to 19:00."},
    }, ["date", "time"], "Books a callback for the customer. CALL it as soon as the person who answered gives a day and time inside the allowed callback window.", post=CALLBACK_POST)


def promise_tool():
    return api_tool("create_promise", {
        "product_id": {"type": "string", "default": "{{product_id}}"},
        "amount": {"type": "number", "default": "{{promise_amount}}", "description": "The agreed amount as a number, e.g. 420.0. Must be between the floor and the full past-due amount."},
        "date": {"type": "string", "default": "{{promise_date}}", "description": "The agreed payment date, YYYY-MM-DD. Must be one of the VALID PROMISE DATES."},
    }, ["amount", "date"], "Records the payment promise. CALL it only right after the customer clearly said yes to your read-back of product, amount and date.",
        post=PROMISE_POST, pre=PROMISE_PRE, retries=0)


def or_eq(var, *vals):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": v} for v in vals]}


def truthy(var):
    return or_eq(var, "true", "True")


def gt0(var):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "greater_than", "operand": 0}]}


TO_END = {"target_node": "end", "description": "close_call was made", "condition": {"logic": "or", "conditions": [
