    return "try:\n    if isinstance(result, dict):\n        result.pop('header', None)\n        d = result.get('data')\n        if not isinstance(d, dict):\n            d = dict()\n            result['data'] = d\n" + "".join("        " + l + "\n" for l in body.strip("\n").split("\n")) + "except Exception:\n    pass\n"

