if d.get('hint') == 'day_month_swapped':
    d['what_to_do_next'] = 'Not accepted yet, and this does NOT count as a wrong answer. Ask the customer to say their date of birth again with the month as a word, for example 14 March 1988.'
elif d.get('ok') is False and 'verified' not in d:
    d['what_to_do_next'] = 'The answer could not be checked (unreadable or a technical problem). This is not a wrong answer. Tell the customer briefly and ask for the same answer again.'
elif d.get('all_verified') is True:
    d['what_to_do_next'] = 'Both security answers are correct. Say thank you.'
elif d.get('verified') is True:
    d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'
elif d.get('wrong_answers_left') == 0:
    d['what_to_do_next'] = 'Third wrong answer: the check has ended. Do not ask again and do not mention any account details.'
else:
    d['what_to_do_next'] = 'The answer does not match our records. Tell the customer it does not match and ask the SAME question once more. Do not reveal the right answer.'
if result.get('status') not in (None, 'success') and 'verified' not in d:
    d['what_to_do_next'] = 'The check failed because of a technical problem. Tell the customer, then ask for the same answer again.'
''')

PROMISE_POST = hook(r'''
if d.get('ok') is True:
