CLOSE_PRE = "try:\n    b = config.get('body')\n    if isinstance(b, dict) and b.get('outcome') in ('promise', 'paid'):\n        b.pop('reason', None)\nexcept Exception:\n    pass\n"
PROMISE_PRE = ("try:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = b.get('amount')\n        if isinstance(a, str):\n            b['amount'] = float(a.replace(',', '').strip())\n"
               "        dt = b.get('date')\n        if isinstance(dt, str):\n            b['date'] = dt.strip()[:10]\nexcept Exception:\n    pass\n")


def api_tool(name, body_props, required, description, post="", pre="", retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": description,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": BASE + name},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if post:
        t["post_process_code"] = post
    if pre:
        t["pre_process_code"] = pre
    return t


def close_tool(allowed):
    """allowed: list of (outcome, reason-or-None) pairs this node may use."""
    outs = sorted({o for o, _ in allowed})
    reasons = sorted({r for _, r in allowed if r})
    combos = "; ".join(o + (" / " + r if r else " (no reason)") for o, r in allowed)
    props = {
        "outcome": {"type": "string", "enum": outs, "default": "{{close_outcome}}", "description": "Outcome of the call. Allowed combinations here: " + combos},
    }
    if reasons:
        props["reason"] = {"type": "string", "enum": reasons, "default": "{{close_reason}}", "description": "Reason that goes with the outcome. Allowed combinations: " + combos + ". Leave empty for promise or paid."}
    return api_tool("close_call", props, ["outcome"],
                    "Ends the call record. CALL it exactly once, as the very last action, in the same message in which you thank the customer and say goodbye. Allowed outcome / reason combinations: " + combos + ".",
                    pre=CLOSE_PRE, retries=1)


def verify_tool(field, desc):
    return api_tool("verify_identity", {
        "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "default": field},
        "answer": {"type": "string", "default": "{{security_answer}}", "description": desc},
    }, ["answer"], "Checks one security answer. CALL it every time the customer gives an answer to the security question, before you say anything about whether it is right.",
        post=VERIFY_POST, retries=1)


def transfer_tool(queue=None):
    if queue:
        q = {"type": "string", "enum": ["restructuring", "general", "support"], "default": queue}
        d = "Hands the call to a human colleague (queue " + queue + "). CALL it only when the customer insists on speaking to a human after you asked once whether you can help."
    else:
        q = {"type": "string", "enum": ["restructuring", "general", "support"], "default": "{{transfer_queue}}",
             "description": "restructuring: customer asks for a new payment plan or lower instalments. support: customer in hardship (illness, death in family, job loss) accepted the offer of the support team. general: customer insists on a human."}
        d = "Hands the call to a human team. CALL it for: a request for a new payment plan or lower instalments (queue restructuring), a hardship customer who accepted the support team (queue support), a customer who insists on a human after you asked once whether you can help (queue general)."
    return api_tool("transfer_to_agent", {"queue": q}, ["queue"], d, post=TRANSFER_POST, retries=0)


def callback_tool():
    return api_tool("schedule_callback", {
        "date": {"type": "string", "default": "{{callback_date}}", "description": "Callback date, YYYY-MM-DD. Must be one of the allowed callback days."},
        "time": {"type": "string", "default": "{{callback_time}}", "description": "Callback time, HH:MM 24-hour, from 10:00 to 19:00."},
    }, ["date", "time"], "Books a callback for the customer. CALL it as soon as the person who answered gives a day and time inside the allowed callback window.", post=CALLBACK_POST)


def promise_tool():
    return api_tool("create_promise", {
        "product_id": {"type": "string", "default": "{{product_id}}"},
        "amount": {"type": "number", "default": "{{promise_amount}}", "description": "The agreed amount as a number, e.g. 420.0. Must be between the floor and the full past-due amount."},
        "date": {"type": "string", "default": "{{promise_date}}", "description": "The agreed payment date, YYYY-MM-DD. Must be one of the VALID PROMISE DATES."},
    }, ["amount", "date"], "Records the payment promise. CALL it only right after the customer clearly said yes to your read-back of product, amount and date.",
        post=PROMISE_POST, pre=PROMISE_PRE, retries=0)


def or_eq(var, *vals):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": v} for v in vals]}


def truthy(var):
    return or_eq(var, "true", "True")


def gt0(var):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "greater_than", "operand": 0}]}


TO_END = {"target_node": "end", "description": "close_call was made", "condition": {"logic": "or", "conditions": [
    {"variable": "close_call_success_count", "operator": "greater_than", "operand": 0},
    {"variable": "close_call_failure_count", "operator": "greater_than", "operand": 1}]}}


def code_node(name, nxt):
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
            "code": {"type": "string", "default": FACTS_CODE}, "timeout_ms": {"type": "number", "default": 15000}}}}}],
        "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


def closer_node(name, line, outcome, reason):
    body = {"customer_id": {"type": "string", "default": "{{customer_id}}"}, "outcome": {"type": "string", "default": outcome}}
    if reason:
        body["reason"] = {"type": "string", "default": reason}
    return {
        "name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": "end",
        "on_enter": {"type": "tts", "text": line}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 1}, "function": {
            "name": "close_call", "handler": "__function__:api_call", "description": "Close the call.",
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + "close_call"},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "properties": body, "required": []}}}}}],
        "transitions": [{"target_node": "end", "description": "always", "condition": {"operator": "always"}}],
    }


